CREATE TABLE cierres_caja(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,fecha DATE NOT NULL UNIQUE,saldo_inicial NUMERIC(12,2) NOT NULL DEFAULT 0,ingresos NUMERIC(12,2) NOT NULL DEFAULT 0,egresos NUMERIC(12,2) NOT NULL DEFAULT 0,devoluciones NUMERIC(12,2) NOT NULL DEFAULT 0,saldo_teorico NUMERIC(12,2) NOT NULL,saldo_contado NUMERIC(12,2) NOT NULL,diferencia NUMERIC(12,2) NOT NULL,observaciones VARCHAR(500),estado VARCHAR(20) NOT NULL DEFAULT 'CERRADO',usuario_id BIGINT NOT NULL REFERENCES usuarios(id),fecha_cierre TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
